def fixed_point_report(g, x0, q, tol):
    """(x, n_post, n_prior, bound) for the iteration of g from x0."""
    if q >= 1:
        raise ValueError("not a contraction")
    d01 = abs(g(x0) - x0)
    n_prior = 0
    while q ** n_prior / (1 - q) * d01 >= tol:
        n_prior += 1
    x, n = x0, 0
    while True:
        x_new = g(x)
        n += 1
        bound = q / (1 - q) * abs(x_new - x)
        if bound < tol:
            return (x_new, n, n_prior, bound)
        x = x_new
